default_resource_check.allocation_harness:
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering};
static CALLS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
struct Counter;
unsafe impl GlobalAlloc for Counter {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(layout.size(), Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(layout.size(), Ordering::Relaxed);
        unsafe { System.alloc_zeroed(layout) }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(size, Ordering::Relaxed);
        unsafe { System.realloc(ptr, layout, size) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) { unsafe { System.dealloc(ptr, layout) } }
}
#[global_allocator]
static ALLOCATOR: Counter = Counter;
fn main() {
    let target = toucan_target::Target::X86_64UnknownLinuxGnu;
    let mut sources = vec![String::from("typedef int T; struct S {int x;}; extern int f(T);"), String::from("int f(int n) { typedef int A[n]; A a; { long n; n=2; } for(int i=0;i<3;i++){ int x=i; } return sizeof a; }")];
    sources.push((0..100).map(|i| format!("int f{i}(int n) {{ int x = n+1; {{ int x=2; }} return x; }}\n")).collect());
    for (index, source) in sources.iter().enumerate() {
        drop(toucan_semantic::analyze(source, target).unwrap());
        CALLS.store(0, Ordering::Relaxed); BYTES.store(0, Ordering::Relaxed);
        let unit = toucan_semantic::analyze(source, target).unwrap();
        let calls = CALLS.load(Ordering::Relaxed); let bytes = BYTES.load(Ordering::Relaxed);
        println!("{index}: {calls} allocations, {bytes} bytes; {} declarations", unit.declarations.len());
    }
}

external_corpus.harness_source:
use std::path::Path;
use toucan_semantic::{AnalysisOptions, analyze, analyze_with_options};
use toucan_target::Target;
fn main() {
    let corpus = Path::new("/home/dev-user/.cache/toucan/conformance/c-testsuite-audit");
    let mut paths: Vec<_> = std::fs::read_dir(corpus).unwrap().map(|entry| entry.unwrap().path().join("source.i")).filter(|path| path.is_file()).collect();
    paths.sort();
    let mut accepted = 0; let mut rejected = 0;
    for path in paths {
        let source = std::fs::read_to_string(&path).unwrap();
        let plain = analyze(&source, Target::X86_64UnknownLinuxGnu);
        let retained = analyze_with_options(&source, Target::X86_64UnknownLinuxGnu, &AnalysisOptions { retain_code: true, ..AnalysisOptions::default() });
        match (plain, retained) {
            (Ok(plain), Ok(retained)) => { assert_eq!(format!("{plain:?}"), format!("{:?}",retained.unit()), "{}", path.display()); assert!(retained.checked().is_some()); accepted += 1; }
            (Err(plain), Err(retained)) => { assert_eq!(plain.to_string(), retained.to_string(), "{}", path.display()); rejected += 1; }
            (plain, retained) => panic!("{}: default={plain:?}, retained={retained:?}", path.display()),
        }
    }
    println!("{accepted} accepted cases with identical unit output; {rejected} identical constraint rejections");
    assert_eq!((accepted,rejected),(219,1));
}

